import 'package:app_movil_sistema/core/network/api_client.dart'; import 'package:app_movil_sistema/core/network/api_response.dart'; import 'package:app_movil_sistema/features/inventory_count/data/datasources/inventory_count_remote_datasource.dart'; import 'package:app_movil_sistema/features/inventory_count/domain/entities/inventory_count.dart'; import 'package:dio/dio.dart';
class InventoryCountRemoteDataSourceImpl implements InventoryCountRemoteDataSource { final ApiClient api; InventoryCountRemoteDataSourceImpl(this.api); InventoryCount _count(Map<String,dynamic> x)=>InventoryCount(id:(x['id'] as num).toInt(),status:x['status'] as String);
 Future<T?> _get<T>(Future<Response> call,T? Function(Object?) map) async {final r=await call;final a=ApiResponse<T?>.fromJson(r.data,map);if(!a.success)throw DioException(requestOptions:r.requestOptions,response:r,error:a.message);return a.data;}
 @override Future<InventoryCount?> current()=>_get(api.dio.get('/inventory-counts/current'),(v)=>v==null?null:_count(v as Map<String,dynamic>));
 @override Future<InventoryCount> open()=>_get(api.dio.post('/inventory-counts',data:{}),(v)=>_count(v as Map<String,dynamic>)).then((v)=>v!);
 @override Future<List<InventoryCountItem>> detail(int id)=>_get(api.dio.get('/inventory-counts/$id'),(v){final rows=(v as Map<String,dynamic>)['items'] as List;return rows.map((r){final x=r as Map<String,dynamic>;final i=x['item'] as Map<String,dynamic>;return InventoryCountItem(productId:(i['productId'] as num).toInt(),productName:x['productName'] as String,productCode:x['productCode'] as String,openingStock:(i['openingStock'] as num).toInt(),physicalStock:(i['physicalStock'] as num?)?.toInt());}).toList();}).then((v)=>v??[]);
 @override Future<InventoryCount> close(int id,List<InventoryCountEntry> items)=>_get(api.dio.put('/inventory-counts/$id/close',data:{'items':items.map((e)=>{'productId':e.productId,'physicalStock':e.physicalStock,'reason':e.reason,'applyAdjustment':e.applyAdjustment}).toList()}),(v)=>_count(v as Map<String,dynamic>)).then((v)=>v!); }
